const TagSelector={render:async function(selector,userOptions){const options={placeholder:"Type to filter...",delimiter:",",inputClass:"",tagClass:"",tagContainerClass:"",tags:[],...userOptions};const element=document.getElementById(selector);let selectedTags=[];element.type="hidden";const input=document.createElement("div");input.className=`is-tag-selector-container ${options.inputClass}`;const inputSearch=document.createElement("input");inputSearch.type="text";inputSearch.placeholder=options.placeholder;inputSearch.className="is-tag-selector-input";inputSearch.addEventListener("focus",function(){input.classList.add("is-tag-selector-focused")});inputSearch.addEventListener("blur",function(){input.classList.remove("is-tag-selector-focused")});inputSearch.addEventListener("input",function(){const filter=this.value.toLowerCase();const tags=tagsContainer.querySelectorAll(".is-tag-selector-tag");tags.forEach(tag=>{tag.classList.add("is-tag-selector-filtered");if(tag.textContent.toLowerCase().includes(filter)){tag.classList.remove("is-tag-selector-filtered")}})});input.appendChild(inputSearch);const tagsContainer=document.createElement("div");tagsContainer.className=`is-tag-selector-tags ${options.tagContainerClass}`;options.tags.forEach(tag=>{const tagElement=document.createElement("a");tagElement.className=`is-tag-selector-tag ${options.tagClass}`;tagElement.textContent=tag.name;tagElement.dataset.value=tag.value;tagsContainer.appendChild(tagElement);const removeTagButton=document.createElement("span");removeTagButton.className="is-tag-selector-remove-tag";removeTagButton.textContent="✕";tagElement.appendChild(removeTagButton);tagElement.addEventListener("click",function(ev){ev.preventDefault();if(selectedTags.includes(this.dataset.value)){selectedTags=selectedTags.filter(tag=>tag!==this.dataset.value);this.remove();this.classList.remove("is-tag-selector-selected");element.value=selectedTags.join(options.delimiter);tagsContainer.appendChild(tagElement)}else{selectedTags=[...selectedTags,this.dataset.value];this.remove();this.classList.add("is-tag-selector-selected");element.value=selectedTags.join(options.delimiter);input.prepend(tagElement)}console.log(element.value)})});element.parentNode.insertBefore(tagsContainer,element.nextSibling);element.parentNode.insertBefore(input,element.nextSibling)}};